namespace SnapsInAZfs.Interop.Zfs.Json;

/// <summary>
///   JSON output generated by <c>zfs get -j</c> commands.
/// </summary>
public class ZfsGetResult
{
 
  /// <summary>
  ///   The output_version property.
  /// </summary>
  /// <remarks>This property is not used by SIAZ.</remarks>
  public OutputVersion output_version { get; set; }

 /// <summary>
  ///   A mapping of dataset names to <see cref="Dataset" /> objects.
  /// </summary>
  public Dictionary<string, Dataset> datasets { get; set; }
}
